(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1RC_0LC0RA_0RA0LD_1RA1LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB1RC_0LC0RA_0RA0LD_1RA1LC.
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (H1 & _).
  unfold Cc_1RB1RC_0LC0RA_0RA0LD_1RA1LC, cden, A0_1RB1RC_0LC0RA_0RA0LD_1RA1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB1RC_0LC0RA_0RA0LD_1RA1LC : forall p j q0, cview p = (j, Some q0) ->
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_1RB1RC_0LC0RA_0RA0LD_1RA1LC = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (_ & H2).
  unfold Cc_1RB1RC_0LC0RA_0RA0LD_1RA1LC, cden, A1_1RB1RC_0LC0RA_0RA0LD_1RA1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1RC_0LC0RA_0RA0LD_1RA1LC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 4). split; [lia|].
  rewrite (gsi_1RB1RC_0LC0RA_0RA0LD_1RA1LC p j q0 E).
  rewrite (srun_sound tm false true chi_1RB1RC_0LC0RA_0RA0LD_1RA1LC A0_1RB1RC_0LC0RA_0RA0LD_1RA1LC A1_1RB1RC_0LC0RA_0RA0LD_1RA1LC 4 4
             run_int_1RB1RC_0LC0RA_0RA0LD_1RA1LC (Ap_Alph_10_11_11 q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB1RC_0LC0RA_0RA0LD_1RA1LC p j q0 E).
Qed.

