    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S0] j ++ [S1;S0;S1], S0, []))).
  { unfold Cin_1RB1RC_0LC0RA_0RA0LD_1RA1LC. rewrite epow2_1RB1RC_0LC0RA_0RA0LD_1RA1LC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1RC_0LC0RA_0RA0LD_1RA1LC. rewrite ?lift_app_blank. reflexivity.
