               run_boot_1RB1RC_0LC0RA_0RA0LD_1RA1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1RC_0LC0RA_0RA0LD_1RA1LC p (pow2 j) (pow2 j));
        [exact HB1|].
      exists (4 * j + 4), (cden [] [] j BM1_1RB1RC_0LC0RA_0RA0LD_1RA1LC).
      split; [| exact (gbo2_1RB1RC_0LC0RA_0RA0LD_1RA1LC j)].
      rewrite (gxi_1RB1RC_0LC0RA_0RA0LD_1RA1LC j).
      exact (srun_sound tm true true chm_1RB1RC_0LC0RA_0RA0LD_1RA1LC BM0_1RB1RC_0LC0RA_0RA0LD_1RA1LC BM1_1RB1RC_0LC0RA_0RA0LD_1RA1LC 4 4
               run_shift_1RB1RC_0LC0RA_0RA0LD_1RA1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    exact HB2.
  - exists (4 * j + 8), (cden [] [] j B1_1RB1RC_0LC0RA_0RA0LD_1RA1LC).
    split; [| exact (geo_1RB1RC_0LC0RA_0RA0LD_1RA1LC p j E)].
    rewrite (gxi2_1RB1RC_0LC0RA_0RA0LD_1RA1LC j).
