(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1RC_0LC0RB_1LA1LD_0RD1LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_00_01_0 q0 ++ [S0;S1;S0]) [] j A0_1RB1RC_0LC0RB_1LA1LD_0RD1LC.
Proof.
  intros p j q0 E. destruct (Alph_00_01_0.cview_some_Alph_00_01_0 p j q0 E) as (H1 & _).
  unfold Cc_1RB1RC_0LC0RB_1LA1LD_0RD1LC, cden, A0_1RB1RC_0LC0RB_1LA1LD_0RD1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S0;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB1RC_0LC0RB_1LA1LD_0RD1LC : forall p j q0, cview p = (j, Some q0) ->
  cden (Ap_Alph_00_01_0 q0 ++ [S0;S1;S0]) [] j A1_1RB1RC_0LC0RB_1LA1LD_0RD1LC = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_00_01_0.cview_some_Alph_00_01_0 p j q0 E) as (_ & H2).
  unfold Cc_1RB1RC_0LC0RB_1LA1LD_0RD1LC, cden, A1_1RB1RC_0LC0RB_1LA1LD_0RD1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S0;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1RC_0LC0RB_1LA1LD_0RD1LC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (6 * j + 4). split; [lia|].
  rewrite (gsi_1RB1RC_0LC0RB_1LA1LD_0RD1LC p j q0 E).
  rewrite (srun_sound tm false true chi_1RB1RC_0LC0RB_1LA1LD_0RD1LC A0_1RB1RC_0LC0RB_1LA1LD_0RD1LC A1_1RB1RC_0LC0RB_1LA1LD_0RD1LC 6 4
             run_int_1RB1RC_0LC0RB_1LA1LD_0RD1LC (Ap_Alph_00_01_0 q0 ++ [S0;S1;S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB1RC_0LC0RB_1LA1LD_0RD1LC p j q0 E).
Qed.

Lemma gso_1RB1RC_0LC0RB_1LA1LD_0RD1LC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1RC_0LC0RB_1LA1LD_0RD1LC.
Proof.
  intros p j E. destruct (Alph_00_01_0.cview_none_Alph_00_01_0 p j E) as (H1 & _).
  unfold Cc_1RB1RC_0LC0RB_1LA1LD_0RD1LC, cden, B0_1RB1RC_0LC0RB_1LA1LD_0RD1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1RC_0LC0RB_1LA1LD_0RD1LC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RC_0LC0RB_1LA1LD_0RD1LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RC_0LC0RB_1LA1LD_0RD1LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_00_01_0.cview_none_Alph_00_01_0 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RC_0LC0RB_1LA1LD_0RD1LC
             = (StB, (rep [S0;S0] (S j) ++ [S0;S0;S1], S0, []))).
  { unfold cden, B1_1RB1RC_0LC0RB_1LA1LD_0RD1LC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S0;S0] (S j) ++ [S0;S0;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1RC_0LC0RB_1LA1LD_0RD1LC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1RC_0LC0RB_1LA1LD_0RD1LC. reflexivity.
Qed.

Lemma gsn_1RB1RC_0LC0RB_1LA1LD_0RD1LC : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ap_Alph_00_01_0 q0 ++ [S1;S1]) [] i AI0_1RB1RC_0LC0RB_1LA1LD_0RD1LC.
