Lemma gsi_1RB1RC_0LC0RB_1LA1LD_1LA1LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_00_01_0 q0 ++ [S0;S1;S0]) [] j A0_1RB1RC_0LC0RB_1LA1LD_1LA1LC.
