Lemma geo_1RB1RC_0LC0RB_1LA1LD_1LA1LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RC_0LC0RB_1LA1LD_1LA1LC) = lift (Cc (Pos.succ p)).
