  destruct (Alph_00_01_0.cview_none_Alph_00_01_0 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1RC_0LC0RB_1LA1LD_1LA1LC, cden, BE0_1RB1RC_0LC0RB_1LA1LD_1LA1LC; cbn [c_st c_l c_h c_r].
