    apply (fire_via_ovf_lift tm Cc lapil_1RB1RC_0LC1LD_1RA0LB_0RA1LB (StB, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1RC_0LC1LD_1RA0LB_0RA1LB [SRotL 1; SWin 1; SCycL 2 0; SWinL 3] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1RC_0LC1LD_1RA0LB_0RA1LB
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1RC_0LC1LD_1RA0LB_0RA1LB (StC, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1RC_0LC1LD_1RA0LB_0RA1LB [SRotL 1; SWin 1; SCycL 2 0; SWinL 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1RC_0LC1LD_1RA0LB_0RA1LB
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1RC_0LC1LD_1RA0LB_0RA1LB
      with (l := []).
