  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1RC_0LC1LD_1RA0LB_0RA1LB (StD, S1)).
    intros p1 j1 E1.
