    halt it and every [srun] below would fail. *)
Definition pins_1RB1RC_0LC1LD_1RA0LD_0RC1LB : list Instr := [].
Definition tmw_1RB1RC_0LC1LD_1RA0LD_0RC1LB : TM := tm_wrap_trs tmm_1RB1RC_0LC1LD_1RA0LD_0RC1LB pins_1RB1RC_0LC1LD_1RA0LD_0RC1LB.
Local Notation tm := tmw_1RB1RC_0LC1LD_1RA0LD_0RC1LB.

Lemma mirror_ok_1RB1RC_0LC1LD_1RA0LD_0RC1LB : mirror_tm tm_1RB1RC_0LC1LD_1RA0LD_0RC1LB = tmm_1RB1RC_0LC1LD_1RA0LD_0RC1LB.
