    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB1RC_0LC1LD_1RA0LD_0RC1LB (p : positive) : cconf := (StC, (Jp p ++ [S1;S0], S0, [])).
Local Notation Cc := Cc_1RB1RC_0LC1LD_1RA0LD_0RC1LB.

(** ** The certificate *)

Definition A0_1RB1RC_0LC1LD_1RA0LD_0RC1LB : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition A1_1RB1RC_0LC1LD_1RA0LD_0RC1LB : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S0] [] 0 0 []).
Definition chi_1RB1RC_0LC1LD_1RA0LD_0RC1LB : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWinR 4].

Lemma run_int_1RB1RC_0LC1LD_1RA0LD_0RC1LB : srun tm false true chi_1RB1RC_0LC1LD_1RA0LD_0RC1LB A0_1RB1RC_0LC1LD_1RA0LD_0RC1LB = Some (A1_1RB1RC_0LC1LD_1RA0LD_0RC1LB, 4, 8).
