Definition B0_1RB1RC_0LC1LD_1RA0LD_0RC1LB : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1RC_0LC1LD_1RA0LD_0RC1LB : sconf := mkC StC (mkS [] [S1;S1] 1 1 [S1;S1;S0;S0]) S0 (mkS [S0] [] 0 0 []).
(** ** The INNER anchor family -- Jp at StC *)
Definition Cin_1RB1RC_0LC1LD_1RA0LD_0RC1LB (v : positive) : cconf := (StC, (Jp v ++ [], S0, [])).
Local Notation Cin := Cin_1RB1RC_0LC1LD_1RA0LD_0RC1LB.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB1RC_0LC1LD_1RA0LD_0RC1LB : forall n, Jp (pow2 n) = rep [S1;S1] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB1RC_0LC1LD_1RA0LD_0RC1LB : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition AI1_1RB1RC_0LC1LD_1RA0LD_0RC1LB : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S0] [] 0 0 []).
Definition chn_1RB1RC_0LC1LD_1RA0LD_0RC1LB : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWinR 4].

Lemma run_inner_1RB1RC_0LC1LD_1RA0LD_0RC1LB : srun tm false true chn_1RB1RC_0LC1LD_1RA0LD_0RC1LB AI0_1RB1RC_0LC1LD_1RA0LD_0RC1LB = Some (AI1_1RB1RC_0LC1LD_1RA0LD_0RC1LB, 4, 8).
