(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1RC_0LC1LD_1RA0LD_0RC1LB : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0;S0]) S0 (mkS [S0] [] 0 0 []).
Definition chb_1RB1RC_0LC1LD_1RA0LD_0RC1LB : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWinR 4].

Lemma run_boot_1RB1RC_0LC1LD_1RA0LD_0RC1LB : srun tm true true chb_1RB1RC_0LC1LD_1RA0LD_0RC1LB B0_1RB1RC_0LC1LD_1RA0LD_0RC1LB = Some (BB1_1RB1RC_0LC1LD_1RA0LD_0RC1LB, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1RC_0LC1LD_1RA0LD_0RC1LB : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1RC_0LC1LD_1RA0LD_0RC1LB : list lstep := [SCycL 2 0; SWin 1; SWinL 7; SCycR 2; SWinR 10; SFoldL 1].

Lemma run_exit_1RB1RC_0LC1LD_1RA0LD_0RC1LB : srun tm true true che_1RB1RC_0LC1LD_1RA0LD_0RC1LB BE0_1RB1RC_0LC1LD_1RA0LD_0RC1LB = Some (B1_1RB1RC_0LC1LD_1RA0LD_0RC1LB, 4, 18).
