(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1RC_0LC1LD_1RA0LD_0RC1LB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S1;S0]) [] j A0_1RB1RC_0LC1LD_1RA0LD_0RC1LB.
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (H1 & _).
  unfold Cc_1RB1RC_0LC1LD_1RA0LD_0RC1LB, cden, A0_1RB1RC_0LC1LD_1RA0LD_0RC1LB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB1RC_0LC1LD_1RA0LD_0RC1LB : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Jp q0 ++ [S1;S0]) [] j A1_1RB1RC_0LC1LD_1RA0LD_0RC1LB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (_ & H2).
  unfold Cc_1RB1RC_0LC1LD_1RA0LD_0RC1LB, cden, A1_1RB1RC_0LC1LD_1RA0LD_0RC1LB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1RC_0LC1LD_1RA0LD_0RC1LB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (4 * j + 8), (cden (Jp q0 ++ [S1;S0]) [] j A1_1RB1RC_0LC1LD_1RA0LD_0RC1LB).
  split; [lia|]. split; [| exact (gei_1RB1RC_0LC1LD_1RA0LD_0RC1LB p j q0 E)].
  rewrite (gsi_1RB1RC_0LC1LD_1RA0LD_0RC1LB p j q0 E).
  exact (srun_sound tm false true chi_1RB1RC_0LC1LD_1RA0LD_0RC1LB A0_1RB1RC_0LC1LD_1RA0LD_0RC1LB A1_1RB1RC_0LC1LD_1RA0LD_0RC1LB 4 8
           run_int_1RB1RC_0LC1LD_1RA0LD_0RC1LB (Jp q0 ++ [S1;S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB1RC_0LC1LD_1RA0LD_0RC1LB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1RC_0LC1LD_1RA0LD_0RC1LB.
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (H1 & _).
  unfold Cc_1RB1RC_0LC1LD_1RA0LD_0RC1LB, cden, B0_1RB1RC_0LC1LD_1RA0LD_0RC1LB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1RC_0LC1LD_1RA0LD_0RC1LB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RC_0LC1LD_1RA0LD_0RC1LB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RC_0LC1LD_1RA0LD_0RC1LB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RC_0LC1LD_1RA0LD_0RC1LB
             = (StC, ((rep [S1;S1] (S j) ++ [S1;S1;S0]) ++ [S0], S0, ([]) ++ [S0]))).
  { unfold cden, B1_1RB1RC_0LC1LD_1RA0LD_0RC1LB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, (rep [S1;S1] (S j) ++ [S1;S1;S0], S0, []))).
  { unfold Cc_1RB1RC_0LC1LD_1RA0LD_0RC1LB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_1RB1RC_0LC1LD_1RA0LD_0RC1LB. reflexivity.
Qed.

Lemma gsn_1RB1RC_0LC1LD_1RA0LD_0RC1LB : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Jp q0 ++ []) [] i AI0_1RB1RC_0LC1LD_1RA0LD_0RC1LB.
