(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1RC_0LC1RA_1RA0LD_1LC0RA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin2 lapin2_1RB1RC_0LC1RA_1RA0LD_1LC0RA p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (4 * j + 7), (cden [] [] j BB1_1RB1RC_0LC1RA_1RA0LD_1LC0RA).
      split; [lia|]. split; [| exact (gbo_1RB1RC_0LC1RA_1RA0LD_1LC0RA j)].
