               run_boot_1RB1RC_0LC1RA_1RA0LD_1LC0RA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1RC_0LC1RA_1RA0LD_1LC0RA p (pow2 j) (pow2 j));
