  | StD, S0 => mk S1 DL StC | StD, S1 => mk S0 DR StB end.

(** Its mirror 1LB1LC_0LC0RC_1RA0LD_1RC0LB: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1RC_0RC0LC_1LA0RD_1LC0RB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DL StC
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S0 DR StC
  | StC, S0 => mk S1 DR StA | StC, S1 => mk S0 DL StD
  | StD, S0 => mk S1 DR StC | StD, S1 => mk S0 DL StB end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1RC_0RC0LC_1LA0RD_1LC0RB : list Instr := [].
Definition tmw_1RB1RC_0RC0LC_1LA0RD_1LC0RB : TM := tm_wrap_trs tmm_1RB1RC_0RC0LC_1LA0RD_1LC0RB pins_1RB1RC_0RC0LC_1LA0RD_1LC0RB.
Local Notation tm := tmw_1RB1RC_0RC0LC_1LA0RD_1LC0RB.

Lemma mirror_ok_1RB1RC_0RC0LC_1LA0RD_1LC0RB : mirror_tm tm_1RB1RC_0RC0LC_1LA0RD_1LC0RB = tmm_1RB1RC_0RC0LC_1LA0RD_1LC0RB.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

