    trailing blanks. *)
Lemma gbo_1RB1RC_0RC0LC_1LA0RD_1LC0RB : forall j, lift (cden [] [] j BB1_1RB1RC_0RC0LC_1LA0RD_1LC0RB) = lift (Cin (pow2 j)).
