Lemma gz_1RB1RC_1LA1LD_1RA0LB_0RA1LD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] 0 Z0_1RB1RC_1LA1LD_1RA0LB_0RA1LD /\
