(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1RC_1LB0RA_1LD0RC_0LD0LA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] 0 Z0_1RB1RC_1LB0RA_1LD0RC_0LD0LA /\
  cden (Kp q0 ++ [S0]) [] 0 Z1_1RB1RC_1LB0RA_1LD0RC_0LD0LA = Cc (Pos.succ p).
