Lemma lapi_1RB1RC_1LB0RA_1LD0RC_0LD0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
