    exists (2 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1RC_1LB0RA_1LD0RC_0LD0LA P0_1RB1RC_1LB0RA_1LD0RC_0LD0LA P1_1RB1RC_1LB0RA_1LD0RC_0LD0LA 2 8
