(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1RC_1LB1LA_1RA0LD_0RC1LD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_1RB1RC_1LB1LA_1RA0LD_0RC1LD.
