Lemma gsi_1RB1RC_1LB1LA_1RD0LC_0RD0LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j A0_1RB1RC_1LB1LA_1RD0LC_0RD0LA.
Proof.
  intros p j q0 E. destruct (KpCounter.cview_some_K p j q0 E) as (H1 & _).
  unfold Cc_1RB1RC_1LB1LA_1RD0LC_0RD0LA, cden, A0_1RB1RC_1LB1LA_1RD0LC_0RD0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB1RC_1LB1LA_1RD0LC_0RD0LA : forall p j q0, cview p = (j, Some q0) ->
