Lemma lapi_1RB1RC_1LB1LA_1RD0LC_0RD0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
