      with (l := [SWin 11; SCycL 1 0; SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1RC_1LB1LA_1RD0LC_0RD0LA
      with (l := [SWin 9]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1RC_1LB1LA_1RD0LC_0RD0LA
      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
