(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1RC_1LC0LA_1RA0LD_0RA0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] j A0_1RB1RC_1LC0LA_1RA0LD_0RA0LC.
