(** ** The lap *)

Lemma lap_1RB1RC_1LC0LA_1RA0LD_0RC1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
