  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RC_1LC0LD_1RA0LD_0RA1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RC_1LC0LD_1RA0LD_0RA1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1RC_1LC0LD_1RA0LD_0RA1LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RC_1LC0LD_1RA0LD_0RA1LD p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by the boot, the chained counts, and that prefix. *)
Lemma firex_1RB1RC_1LC0LD_1RA0LD_0RA1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1RC_1LC0LD_1RA0LD_0RA1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin (pow2 j))).
  { exists (4 * j + 8), (cden [] [] j BB1_1RB1RC_1LC0LD_1RA0LD_0RA1LD).
    split; [lia|]. split; [| exact (gbo_1RB1RC_1LC0LD_1RA0LD_0RA1LD j)].
    rewrite (gso_1RB1RC_1LC0LD_1RA0LD_0RA1LD p j E).
    exact (srun_sound tm true true chb_1RB1RC_1LC0LD_1RA0LD_0RA1LD B0_1RB1RC_1LC0LD_1RA0LD_0RA1LD BB1_1RB1RC_1LC0LD_1RA0LD_0RA1LD 4 8
             run_boot_1RB1RC_1LC0LD_1RA0LD_0RA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin2 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1RC_1LC0LD_1RA0LD_0RA1LD p (pow2 j) (pow2 j));
      [exact HB1|].
    exists (4 * j + 4), (cden [] [] j BM1_1RB1RC_1LC0LD_1RA0LD_0RA1LD).
    split; [| exact (gbo2_1RB1RC_1LC0LD_1RA0LD_0RA1LD j)].
    rewrite (gxi_1RB1RC_1LC0LD_1RA0LD_0RA1LD j).
    exact (srun_sound tm true true chm_1RB1RC_1LC0LD_1RA0LD_0RA1LD BM0_1RB1RC_1LC0LD_1RA0LD_0RA1LD BM1_1RB1RC_1LC0LD_1RA0LD_0RA1LD 4 4
             run_shift_1RB1RC_1LC0LD_1RA0LD_0RA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  destruct HB2 as (nB & cB & _ & HcB & HlB).
  apply (fire_via_fill tm Cc Cin2 lapin2_1RB1RC_1LC0LD_1RA0LD_0RA1LD t p (pow2 j));
    [exists nB, cB; exact (conj HcB HlB)|].
  apply (fire_lift_of_csteps tm (fun _ : positive => Cin2 (fill (pow2 j))) xH).
  apply (fire_of_run_instr tm (fun _ : positive => Cin2 (fill (pow2 j)))
                    true true l BE0_1RB1RC_1LC0LD_1RA0LD_0RA1LD xH j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gxi2_1RB1RC_1LC0LD_1RA0LD_0RA1LD j)].
Qed.

