                /\ lift c = lift (Cin2 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1RC_1LC0LD_1RA0LD_0RC1LD p (pow2 j) (pow2 j));
      [exact HB1|].
    exists (4 * j + 8), (cden [] [] j BM1_1RB1RC_1LC0LD_1RA0LD_0RC1LD).
    split; [| exact (gbo2_1RB1RC_1LC0LD_1RA0LD_0RC1LD j)].
    rewrite (gxi_1RB1RC_1LC0LD_1RA0LD_0RC1LD j).
    exact (srun_sound tm true true chm_1RB1RC_1LC0LD_1RA0LD_0RC1LD BM0_1RB1RC_1LC0LD_1RA0LD_0RC1LD BM1_1RB1RC_1LC0LD_1RA0LD_0RC1LD 4 8
             run_shift_1RB1RC_1LC0LD_1RA0LD_0RC1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
