    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RC_1LC0RD_1LA1LB_0LC1RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RC_1LC0RD_1LA1LB_0LC1RD = Some t ->
