  apply (fire_of_run_instr tm Cc true true l B0_1RB1RC_1LC0RD_1LA1LB_0LC1RD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RC_1LC0RD_1LA1LB_0LC1RD p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by the boot, the chained counts, and that prefix. *)
Lemma firex_1RB1RC_1LC0RD_1LA1LB_0LC1RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1RC_1LC0RD_1LA1LB_0LC1RD = Some t ->
