                /\ lift c = lift (Cin (pow2 j))).
  { exists (4 * j + 8), (cden [] [] j BB1_1RB1RC_1LC0RD_1LA1LB_0LC1RD).
    split; [lia|]. split; [| exact (gbo_1RB1RC_1LC0RD_1LA1LB_0LC1RD j)].
